-- Tri An Su Phu, November 2026. Optional: the JAR also registers this catalog at startup.
-- Only inserts missing rows; never overwrites existing item/NPC/option IDs.
CREATE TABLE IF NOT EXISTS november2026_players (player_id BIGINT PRIMARY KEY,player_name VARCHAR(100) NOT NULL,score BIGINT NOT NULL DEFAULT 0,reached_at BIGINT NOT NULL DEFAULT 0,data LONGTEXT NOT NULL) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS november2026_meta (id INT PRIMARY KEY,settled INT NOT NULL) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS november2026_winners (player_id BIGINT PRIMARY KEY,rank_no INT NOT NULL,score BIGINT NOT NULL,player_name VARCHAR(100) NOT NULL) ENGINE=InnoDB;

